const _poly = require("_poly");
module.exports = {
  move(dir, speed) {
    if (_poly.sim_get("estop") === true) {
      _poly.sim_set("moving", false);
      _poly.sim_set("speed", 0);
      _poly.sim_set("log:append", "[ESTOP] 急停已触发，忽略移动指令");
      console.log("[WARN] [Mock Robot] E-Stop active, move ignored");
      return;
    }
    const spd = Number(speed) || 0;
    _poly.sim_set("moving", spd > 0);
    _poly.sim_set("speed", spd);
    _poly.sim_set("log:append", `move(${dir}, ${Math.trunc(spd)}%)`);
    console.log(`[INFO] [Mock Robot] move(${dir}, speed=${spd})`);
  },
  battery() {
    const v = Number(_poly.sim_get("battery"));
    return Number.isFinite(v) ? Math.trunc(v) : 88;
  },
};
